/* quién sale en cada escena, para tenerlo hecho antes de que empiece */
export const REPARTO = {10: [['nino', 'nina'], ['senor', 'vecino'], ['madre', 'vecina']], 12: [['senor', 'fotografo']], 20: [['senor', 'noel']], 24: [['madre', 'abuela'], ['senor', 'mayor']]};
