const TRAZO = [[.06, .72, .94, .72], [.12, .72, .12, .42], [.12, .42, .34, .42], [.34, .42, .34, .72], [.4, .72, .4, .46], [.4, .46, .62, .46], [.62, .46, .62, .72], [.66, .72, .66, .3], [.66, .3, .76, .3], [.76, .3, .76, .48], [.76, .48, .9, .48], [.9, .48, .9, .72], [.84, .48, .84, .34], [.18, .78, 0], [.28, .78, 0], [.46, .78, 0], [.56, .78, 0], [.71, .78, 0], [.82, .78, 0], [.84, .26, 1], [.8, .16, 1], [.72, .1, 1]];
